  "summary": "제주는 산소통 없이 맨몸으로 잠수하는 해녀 문화로 유명하며, 이 전통 물질 기술은 2016년 유네스코 인류무형문화유산으로 등재되었습니다. 서귀포 앞바다의 문섬과 범섬은 천연기념물로 지정된 무인도로, 화려한 연산호 군락을 볼 수 있는 세계적인 스쿠버다이빙 포인트로 알려져 있습니다. 한편 강원도 고성·강릉 일대의 동해는 한류와 난류가 교차해 시야가 비교적 좋고, 대문어와 인공 침선(난파선) 다이빙으로 국내 다이버들에게 사랑받는 또 다른 매력의 다이빙 지역입니다. 제주는 사계절 다이빙이 가능하지만 겨울철 수온이 낮아 두꺼운 웻슈트 또는 드라이슈트가 필요하며, 동해는 겨울 저층 수온이 2~4°C까지 내려가 드라이슈트가 사실상 필수입니다. 최근 몇 년간 여름철 고수온 현상으로 제주 일부 연산호 군락이 피해를 입은 사례가 보고되어 방문 전 최신 상태 확인이 권장됩니다.",
